import json
import re
import copy
from docx import Document
from lxml import etree

NSMAP = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

def get_all_paragraphs(doc):
    """Get all paragraphs from the document body, including those inside tables (nested)."""
    paragraphs = []
    for p in doc.element.body.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
        paragraphs.append(p)
    return paragraphs

def get_paragraph_text(p_elem):
    """Get full text of a paragraph element by joining all w:t elements in w:r elements."""
    texts = []
    for r in p_elem.findall('.//w:r', NSMAP):
        for t in r.findall('w:t', NSMAP):
            if t.text:
                texts.append(t.text)
    return ''.join(texts)

def replace_in_paragraph(p_elem, replacements):
    """
    Replace placeholders in a paragraph element.
    Handles the case where placeholders are split across multiple runs.
    Strategy: collect all runs, join their text, do replacements, then redistribute.
    """
    runs = p_elem.findall('.//w:r', NSMAP)
    if not runs:
        return

    # Collect text from each run
    run_texts = []
    for r in runs:
        t_elem = r.find('w:t', NSMAP)
        run_texts.append(t_elem.text if t_elem is not None and t_elem.text else '')

    full_text = ''.join(run_texts)

    # Check if any placeholder exists in this paragraph
    has_placeholder = False
    for key in replacements:
        if key in full_text:
            has_placeholder = True
            break

    if not has_placeholder:
        return

    # Perform all replacements
    new_text = full_text
    for key, value in replacements.items():
        new_text = new_text.replace(key, value)

    # Strategy: put all text into the first run, clear the rest
    # But preserve formatting of the first run
    if runs:
        # Put all replaced text in first run
        first_t = runs[0].find('w:t', NSMAP)
        if first_t is None:
            first_t = etree.SubElement(runs[0], '{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t')
        first_t.text = new_text
        # Preserve spaces
        first_t.set('{http://www.w3.org/XML/1998/namespace}space', 'preserve')

        # Clear text from remaining runs
        for r in runs[1:]:
            t_elem = r.find('w:t', NSMAP)
            if t_elem is not None:
                t_elem.text = ''

def handle_relocation_conditional(doc, keep_content):
    """Handle the {{IF_RELOCATION}}...{{END_IF_RELOCATION}} conditional block."""
    # Find all paragraphs across the entire document (body, headers, footers)
    all_p_elems = list(doc.element.body.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'))

    for p_elem in all_p_elems:
        text = get_paragraph_text(p_elem)
        if '{{IF_RELOCATION}}' in text:
            if keep_content:
                # Remove the markers but keep the content between them
                replace_in_paragraph(p_elem, {
                    '{{IF_RELOCATION}}': '',
                    '{{END_IF_RELOCATION}}': ''
                })
            else:
                # Remove the entire paragraph
                parent = p_elem.getparent()
                if parent is not None:
                    parent.remove(p_elem)

def main():
    # Load data
    with open('/root/employee_data.json', 'r') as f:
        data = json.load(f)

    # Open template
    doc = Document('/root/offer_letter_template.docx')

    # Build replacements dict
    replacements = {}
    for key, value in data.items():
        if key not in ('RELOCATION_PACKAGE',):  # Skip control fields
            placeholder = '{{' + key + '}}'
            replacements[placeholder] = str(value)

    # Determine if relocation content should be kept
    keep_relocation = data.get('RELOCATION_PACKAGE', 'No').lower() == 'yes'

    # Handle conditional section first (before general replacements eat the markers)
    handle_relocation_conditional(doc, keep_relocation)

    # Process all paragraphs in the document body (including nested tables)
    for p_elem in doc.element.body.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
        replace_in_paragraph(p_elem, replacements)

    # Process headers and footers
    for section in doc.sections:
        for header_footer in [section.header, section.footer]:
            for p_elem in header_footer.element.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}p'):
                replace_in_paragraph(p_elem, replacements)

    # Save the result
    doc.save('/root/offer_letter_filled.docx')
    print("Offer letter saved to /root/offer_letter_filled.docx")

if __name__ == '__main__':
    main()
